import Content from './sortable-content.svelte';
import ItemHandle from './sortable-item-handle.svelte';
import Item from './sortable-item.svelte';
import Overlay from './sortable-overlay.svelte';
import Root from './sortable.svelte';

// The root renders no element of its own, so — unlike every other part — it has no `child` snippet
// and therefore no `SortableChildProps` payload type (contract §3).
export type { SortableProps, SortableRootProps } from './sortable.svelte';
export type { SortableContentChildProps, SortableContentProps } from './sortable-content.svelte';
export type { SortableItemChildProps, SortableItemProps } from './sortable-item.svelte';
export type {
	SortableItemHandleChildProps,
	SortableItemHandleProps
} from './sortable-item-handle.svelte';
export type { SortableOverlayProps } from './sortable-overlay.svelte';

export {
	DEFAULT_SORTABLE_ANNOUNCEMENTS,
	SortableItemState,
	SortableRootState,
	assertItemValueGetter,
	getSortableContext,
	getSortableItemContext,
	setSortableContext,
	setSortableItemContext,
	toItemValues,
	useSortable,
	type SortableAccessibility,
	type SortableAnnouncementArgs,
	type SortableAnnouncements,
	type SortableContentContext,
	type SortableDragEvent,
	type SortableItemStateProps,
	type SortableMoveEvent,
	type SortableOrientation,
	type SortableRootStateProps,
	type SortableSessionAnnouncementArgs
} from './sortable.svelte.js';

export {
	DndState,
	DragSession,
	type DndNodeEntry,
	type DndNodeKind,
	type DndStateProps,
	type DragActivator,
	type DragSessionProps,
	type DragSource
} from './sortable-dnd.svelte.js';

export {
	SORTABLE_ORIENTATIONS,
	arrayMove,
	closestCenter,
	closestCorners,
	horizontalListSortingStrategy,
	rectSortingStrategy,
	resolveKeyboardIndex,
	restrictToHorizontalAxis,
	restrictToParentElement,
	restrictToVerticalAxis,
	toClientRect,
	translate3d,
	verticalListSortingStrategy,
	type ClientRect,
	type Coordinates,
	type ResolveKeyboardIndexArgs,
	type SortableArrowKey,
	type SortableCollision,
	type SortableCollisionDetection,
	type SortableModifier,
	type SortableStrategy,
	type SortableStrategyArgs,
	type UniqueIdentifier
} from './sortable-geometry.js';

export {
	Root,
	Content,
	Item,
	ItemHandle,
	Overlay,
	//
	Root as Sortable,
	Content as SortableContent,
	Item as SortableItem,
	ItemHandle as SortableItemHandle,
	Overlay as SortableOverlay
};

/**
 * Pure geometry for the sortable drag engine — no runes, no DOM writes, no component knowledge.
 *
 * Everything here is a total, side-effect-free function over plain objects, which is what makes it
 * unit-testable without a DOM and reusable verbatim by the upcoming `kanban` port. It replaces the
 * parts of `@dnd-kit/core`, `@dnd-kit/sortable`, `@dnd-kit/modifiers` and `@dnd-kit/utilities` the
 * upstream React component depends on.
 */

/** dnd-kit's `UniqueIdentifier`. */
export type UniqueIdentifier = string | number;

export type Coordinates = { x: number; y: number };

/** A snapshot of `getBoundingClientRect()` — never a live `DOMRect`. */
export type ClientRect = {
	top: number;
	left: number;
	right: number;
	bottom: number;
	width: number;
	height: number;
};

/** Every value {@link SortableOrientation} accepts, in upstream declaration order. */
export const SORTABLE_ORIENTATIONS = ['vertical', 'horizontal', 'mixed'] as const;

export type SortableOrientation = (typeof SORTABLE_ORIENTATIONS)[number];

/** One ranked droppable, nearest first. */
export type SortableCollision = { id: UniqueIdentifier; distance: number };

export type SortableCollisionDetection = (args: {
	collisionRect: ClientRect;
	droppables: { id: UniqueIdentifier; rect: ClientRect }[];
}) => SortableCollision[];

export type SortableModifier = (args: {
	transform: Coordinates;
	activeRect: ClientRect | null;
	containerRect: ClientRect | null;
}) => Coordinates;

export type SortableStrategyArgs = {
	index: number;
	activeIndex: number;
	overIndex: number;
	rects: ClientRect[];
	activeRect: ClientRect | null;
};

export type SortableStrategy = (args: SortableStrategyArgs) => Coordinates | null;

/** The four keys {@link resolveKeyboardIndex} understands. */
export type SortableArrowKey = 'ArrowUp' | 'ArrowDown' | 'ArrowLeft' | 'ArrowRight';

export type ResolveKeyboardIndexArgs = {
	key: SortableArrowKey;
	orientation: SortableOrientation;
	dir: 'ltr' | 'rtl';
	activeIndex: number;
	/** One entry per item in the root's `items` array, in that order. */
	candidates: { id: UniqueIdentifier; disabled: boolean; rect: ClientRect | null }[];
};

/** Snapshot an element's box as a plain, non-live {@link ClientRect}. */
export function toClientRect(element: Element): ClientRect {
	const { top, left, right, bottom, width, height } = element.getBoundingClientRect();
	return { top, left, right, bottom, width, height };
}

/**
 * The nearest ancestor that actually generates a layout box.
 *
 * A `display: contents` element produces no box, so `getBoundingClientRect()` answers a zero rect at
 * the viewport origin. Measuring one as the drag container would clamp every transform to the
 * top-left corner and make every collision test miss — which is exactly what happens when an item is
 * rendered through `bits-ui`'s `Command.Item`, since it wraps each child in a `display: contents`
 * div. Walking past those wrappers lands on the element the item is visually laid out in.
 *
 * Only `display: contents` is skipped, never a merely empty box: a container that is genuinely 0×0
 * is a real constraint, and under jsdom — where nothing is laid out — every rect is 0×0.
 */
export function layoutParentOf(node: Element): HTMLElement | null {
	let parent = node.parentElement;
	while (parent && getComputedStyle(parent).display === 'contents') {
		parent = parent.parentElement;
	}
	return parent;
}

/** Replaces `CSS.Translate.toString`. Returns `undefined` so it can be dropped from a style string. */
export function translate3d(transform: Coordinates | null | undefined): string | undefined {
	if (!transform) return undefined;
	return `translate3d(${transform.x}px, ${transform.y}px, 0)`;
}

/**
 * Move `from` to `to`, returning a new array. Out-of-range indices return an unchanged copy, so a
 * caller never has to guard a `-1` from `indexOf`.
 */
export function arrayMove<T>(array: T[], from: number, to: number): T[] {
	const next = array.slice();
	if (from < 0 || from >= array.length || to < 0 || to >= array.length) return next;
	const [item] = next.splice(from, 1);
	next.splice(to, 0, item);
	return next;
}

function centerOf(rect: ClientRect): Coordinates {
	return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
}

function distanceBetween(a: Coordinates, b: Coordinates): number {
	return Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2);
}

function cornersOf(rect: ClientRect): Coordinates[] {
	return [
		{ x: rect.left, y: rect.top },
		{ x: rect.right, y: rect.top },
		{ x: rect.left, y: rect.bottom },
		{ x: rect.right, y: rect.bottom }
	];
}

/** Ranks droppables by the distance between their centre and the collision rect's centre. */
export const closestCenter: SortableCollisionDetection = ({ collisionRect, droppables }) => {
	const center = centerOf(collisionRect);
	return droppables
		.map(({ id, rect }) => ({ id, distance: distanceBetween(center, centerOf(rect)) }))
		.sort((a, b) => a.distance - b.distance);
};

/** Ranks droppables by the summed distance between the four corresponding corners. */
export const closestCorners: SortableCollisionDetection = ({ collisionRect, droppables }) => {
	const corners = cornersOf(collisionRect);
	return droppables
		.map(({ id, rect }) => {
			const others = cornersOf(rect);
			const distance = corners.reduce(
				(total, corner, index) => total + distanceBetween(corner, others[index]),
				0
			);
			return { id, distance };
		})
		.sort((a, b) => a.distance - b.distance);
};

/** dnd-kit's `getItemGap`, on whichever axis the caller names. */
function itemGap(
	rects: ClientRect[],
	index: number,
	activeIndex: number,
	start: 'top' | 'left',
	size: 'height' | 'width'
): number {
	const current = rects[index];
	if (!current) return 0;

	const previous = rects[index - 1];
	const next = rects[index + 1];

	if (activeIndex < index) {
		if (previous) return current[start] - (previous[start] + previous[size]);
		return next ? next[start] - (current[start] + current[size]) : 0;
	}
	if (next) return next[start] - (current[start] + current[size]);
	return previous ? current[start] - (previous[start] + previous[size]) : 0;
}

function listStrategy(start: 'top' | 'left', size: 'height' | 'width'): SortableStrategy {
	const axis = start === 'top' ? 'y' : 'x';
	const zero = { x: 0, y: 0 };

	return ({ index, activeIndex, overIndex, rects, activeRect }) => {
		const active = rects[activeIndex] ?? activeRect;
		if (!active) return null;

		if (index === activeIndex) {
			const overRect = rects[overIndex];
			if (!overRect) return null;
			const offset =
				activeIndex < overIndex
					? overRect[start] + overRect[size] - (active[start] + active[size])
					: overRect[start] - active[start];
			return axis === 'y' ? { x: 0, y: offset } : { x: offset, y: 0 };
		}

		const gap = itemGap(rects, index, activeIndex, start, size);

		if (index > activeIndex && index <= overIndex) {
			const offset = -active[size] - gap;
			return axis === 'y' ? { x: 0, y: offset } : { x: offset, y: 0 };
		}
		if (index < activeIndex && index >= overIndex) {
			const offset = active[size] + gap;
			return axis === 'y' ? { x: 0, y: offset } : { x: offset, y: 0 };
		}
		return { ...zero };
	};
}

/** Shifts items along the block axis; the default for `orientation="vertical"`. */
export const verticalListSortingStrategy: SortableStrategy = listStrategy('top', 'height');

/** Shifts items along the inline axis; the default for `orientation="horizontal"`. */
export const horizontalListSortingStrategy: SortableStrategy = listStrategy('left', 'width');

/**
 * Moves every item into the slot it would occupy after the reorder; the default for
 * `orientation="mixed"` (dnd-kit's own `SortableContext` default, which upstream reaches by leaving
 * `orientationConfig.mixed.strategy` undefined).
 */
export const rectSortingStrategy: SortableStrategy = ({ index, activeIndex, overIndex, rects }) => {
	const nextRects = arrayMove(rects, overIndex, activeIndex);
	const oldRect = rects[index];
	const newRect = nextRects[index];
	if (!oldRect || !newRect) return null;
	return { x: newRect.left - oldRect.left, y: newRect.top - oldRect.top };
};

/** Drops the inline component of the transform. */
export const restrictToVerticalAxis: SortableModifier = ({ transform }) => ({
	x: 0,
	y: transform.y
});

/** Drops the block component of the transform. */
export const restrictToHorizontalAxis: SortableModifier = ({ transform }) => ({
	x: transform.x,
	y: 0
});

/**
 * Clamps the transform so the translated active rect stays inside its container.
 *
 * The container is the dragged node's own parent element, not the `<Sortable.Content>` element —
 * that distinction is what keeps `withoutSlot` and the `child`-onto-`<Table.Body>` composition
 * working (research R-07).
 */
export const restrictToParentElement: SortableModifier = ({
	transform,
	activeRect,
	containerRect
}) => {
	if (!activeRect || !containerRect) return transform;

	let { x, y } = transform;

	if (activeRect.top + y < containerRect.top) {
		y = containerRect.top - activeRect.top;
	} else if (activeRect.bottom + y > containerRect.bottom) {
		y = containerRect.bottom - activeRect.bottom;
	}

	if (activeRect.left + x < containerRect.left) {
		x = containerRect.left - activeRect.left;
	} else if (activeRect.right + x > containerRect.right) {
		x = containerRect.right - activeRect.right;
	}

	return { x, y };
};

function isDegenerate(rect: ClientRect | null | undefined): boolean {
	return !rect || (rect.width === 0 && rect.height === 0);
}

function nearestInDirection(
	key: SortableArrowKey,
	activeIndex: number,
	activeRect: ClientRect,
	candidates: ResolveKeyboardIndexArgs['candidates']
): number | null {
	const from = centerOf(activeRect);
	let best: { index: number; primary: number; total: number } | null = null;

	for (let index = 0; index < candidates.length; index++) {
		if (index === activeIndex) continue;

		const candidate = candidates[index];
		if (candidate.disabled || isDegenerate(candidate.rect) || !candidate.rect) continue;

		const to = centerOf(candidate.rect);
		const dx = to.x - from.x;
		const dy = to.y - from.y;

		const primary =
			key === 'ArrowUp' ? -dy : key === 'ArrowDown' ? dy : key === 'ArrowLeft' ? -dx : dx;
		if (primary <= 0) continue;

		const total = Math.sqrt(dx ** 2 + dy ** 2);
		if (!best || primary < best.primary || (primary === best.primary && total < best.total)) {
			best = { index, primary, total };
		}
	}

	return best?.index ?? null;
}

/**
 * The keyboard sensor's whole decision: which index an arrow key moves the grabbed item to, or
 * `null` when the key does not apply on this axis and no target exists.
 *
 * Index-first rather than dnd-kit's coordinate-first `sortableKeyboardCoordinates`: for list
 * orientations the observable result is identical, and it stays correct on a container that has not
 * been laid out yet — which is also what makes the whole keyboard contract assertable under jsdom
 * (research R-04).
 */
export function resolveKeyboardIndex(args: ResolveKeyboardIndexArgs): number | null {
	const { orientation, dir, activeIndex, candidates } = args;

	// 1. RTL mirror — `horizontal` and `mixed` only; `vertical` is unaffected by direction.
	let key = args.key;
	if (dir === 'rtl' && orientation !== 'vertical') {
		if (key === 'ArrowLeft') key = 'ArrowRight';
		else if (key === 'ArrowRight') key = 'ArrowLeft';
	}

	// 2. Axis filter.
	const isInline = key === 'ArrowLeft' || key === 'ArrowRight';
	if (orientation === 'vertical' && isInline) return null;
	if (orientation === 'horizontal' && !isInline) return null;

	if (activeIndex < 0 || activeIndex >= candidates.length) return null;

	// 3. `mixed` with real geometry — nearest enabled centre strictly in the pressed direction.
	if (orientation === 'mixed') {
		const activeRect = candidates[activeIndex].rect;
		const discriminates =
			!isDegenerate(activeRect) &&
			candidates.some(
				(candidate, index) =>
					index !== activeIndex && !candidate.disabled && !isDegenerate(candidate.rect)
			);
		if (discriminates && activeRect) {
			return nearestInDirection(key, activeIndex, activeRect, candidates);
		}
	}

	// 4. List orientations, or a grid whose rects do not discriminate — step to the nearest enabled
	//    index in the key's direction.
	const step = key === 'ArrowUp' || key === 'ArrowLeft' ? -1 : 1;
	for (let index = activeIndex + step; index >= 0 && index < candidates.length; index += step) {
		if (!candidates[index].disabled) return index;
	}

	// 5. Nothing to move to.
	return null;
}

/**
 * The sensor-agnostic drag engine: a droppable registry, a pointer sensor, a keyboard sensor and a
 * single {@link DragSession} at a time.
 *
 * It knows nothing about `value`, `getItemValue`, orientation or announcements — those are injected
 * as getter functions by the component layer, which is what lets the upcoming `kanban` port import
 * this file unchanged (research R-01/R-02).
 */

import {
	layoutParentOf,
	toClientRect,
	type ClientRect,
	type Coordinates,
	type SortableArrowKey,
	type SortableCollisionDetection,
	type SortableModifier,
	type UniqueIdentifier
} from './sortable-geometry.js';

/** `'item'` is draggable and droppable; `'container'` is the seam `kanban` will register columns on. */
export type DndNodeKind = 'item' | 'container';

/** One registered node. Registration is imperative and non-reactive by design (research R-19). */
export type DndNodeEntry = {
	id: UniqueIdentifier;
	kind: DndNodeKind;
	/** Which region owns it. `sortable` fills this from the nearest `<Sortable.Content>`. */
	containerId: UniqueIdentifier | null;
	node: HTMLElement;
	/** A getter, so a disabled entry is neither draggable nor droppable at the moment it is read. */
	disabled: () => boolean;
};

export type DragSource = 'pointer' | 'keyboard';

export type DragActivator = PointerEvent | KeyboardEvent;

/** Mouse and pen drags start after this much movement. */
const POINTER_ACTIVATION_DISTANCE = 5;

/** Touch drags start after this much hold, and are abandoned if the finger moves first. */
const TOUCH_ACTIVATION_DELAY = 250;

/** A press on one of these never starts a drag, unless the element *is* the activator. */
const INTERACTIVE_SELECTOR = 'button, input, select, textarea, a[href], [contenteditable="true"]';

export type DragSessionProps = {
	readonly activeId: UniqueIdentifier;
	readonly source: DragSource;
	readonly activatorEvent: DragActivator;
	readonly initialIndex: number;
	readonly initialCoordinates: Coordinates;
	readonly activeRect: ClientRect | null;
	readonly containerRect: ClientRect | null;
	readonly rects: ReadonlyMap<UniqueIdentifier, ClientRect>;
	readonly getModifiers: () => SortableModifier[];
};

/** The transient state that exists only while a drag is active. */
export class DragSession {
	// `$derived` below is lazy at runtime (evaluated only when `.transform` is read), but
	// svelte-check's static analysis cannot see that and flags the field as used before its
	// constructor assignment.
	#props!: DragSessionProps;

	/** Raw pointer delta, before the modifier chain. */
	delta = $state<Coordinates>({ x: 0, y: 0 });
	/** The current drop target. Starts as the dragged item itself, as dnd-kit's `over` does. */
	overId = $state<UniqueIdentifier | null>(null);
	/** Set by `Escape`, by a pointer cancel, and by mid-drag removal of the active item. */
	cancelled = $state(false);

	/** The modifier-clamped delta. Never stored — always derived from {@link delta}. */
	readonly transform: Coordinates = $derived(
		this.#props.getModifiers().reduce(
			(transform, modifier) =>
				modifier({
					transform,
					activeRect: this.#props.activeRect,
					containerRect: this.#props.containerRect
				}),
			this.delta
		)
	);

	constructor(props: DragSessionProps) {
		this.#props = props;
	}

	get activeId(): UniqueIdentifier {
		return this.#props.activeId;
	}

	get source(): DragSource {
		return this.#props.source;
	}

	get activatorEvent(): DragActivator {
		return this.#props.activatorEvent;
	}

	/** The active item's position at pick-up — the cancel announcement's number. */
	get initialIndex(): number {
		return this.#props.initialIndex;
	}

	get initialCoordinates(): Coordinates {
		return this.#props.initialCoordinates;
	}

	get activeRect(): ClientRect | null {
		return this.#props.activeRect;
	}

	get containerRect(): ClientRect | null {
		return this.#props.containerRect;
	}

	/** Immutable snapshot of every item's rect, taken at pick-up. */
	get rects(): ReadonlyMap<UniqueIdentifier, ClientRect> {
		return this.#props.rects;
	}
}

export type DndStateProps = {
	/** The ordered identifier space a drag resolves against. */
	readonly getItems: () => UniqueIdentifier[];
	readonly getModifiers: () => SortableModifier[];
	readonly getCollisionDetection: () => SortableCollisionDetection;
	/** Narrow the droppables a drag may resolve against. Defaults to every enabled item. */
	readonly filterDroppables?: (candidates: DndNodeEntry[], active: DndNodeEntry) => DndNodeEntry[];
	readonly onStart?: (session: DragSession) => void;
	readonly onMove?: (session: DragSession) => void;
	readonly onOver?: (session: DragSession) => void;
	readonly onEnd?: (session: DragSession) => void;
	readonly onCancel?: (session: DragSession) => void;
	/** Resolve an arrow key to a target index, or `null` to leave the item where it is. */
	readonly onArrowKey?: (key: SortableArrowKey, session: DragSession) => number | null;
};

type PointerActivation = {
	entry: DndNodeEntry;
	event: PointerEvent;
	activator: HTMLElement;
	origin: Coordinates;
	pointerId: number;
	timer: ReturnType<typeof setTimeout> | null;
	captured: boolean;
};

function translateRect(rect: ClientRect, transform: Coordinates): ClientRect {
	return {
		top: rect.top + transform.y,
		bottom: rect.bottom + transform.y,
		left: rect.left + transform.x,
		right: rect.right + transform.x,
		width: rect.width,
		height: rect.height
	};
}

function intersects(a: ClientRect, b: ClientRect): boolean {
	return a.left <= b.right && a.right >= b.left && a.top <= b.bottom && a.bottom >= b.top;
}

function centerOf(rect: ClientRect): Coordinates {
	return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
}

/**
 * Build the immutable rect snapshot a session reasons about. Constructed here rather than inline so
 * the "measured once, never mutated" promise is what the type says and what the code can do.
 */
function toRectMap(
	measured: Array<[UniqueIdentifier, ClientRect]>
): ReadonlyMap<UniqueIdentifier, ClientRect> {
	return new Map(measured);
}

/**
 * Owns the droppable registry and at most one open {@link DragSession}.
 *
 * It holds exactly three long-lived resources — the document `pointermove`/`pointerup`/
 * `pointercancel`/`keydown` listeners, the touch-activation timer and the pointer capture — and
 * {@link DndState.destroy} releases all three.
 */
export class DndState {
	#props: DndStateProps;
	/**
	 * A plain, non-reactive array — deliberately not a `SvelteMap` (research R-19): a reactive
	 * container would make each item's registration effect a dependent of the very signal it writes.
	 * Nothing in the render path reacts to *registration*, only to the drag session. Same shape as
	 * `tour`'s `TourStepRegistry`.
	 */
	#nodes: DndNodeEntry[] = [];
	#pointer: PointerActivation | null = null;
	#pointerListening = false;
	#keyListening = false;

	session = $state<DragSession | null>(null);

	readonly activeId: UniqueIdentifier | null = $derived(this.session?.activeId ?? null);
	readonly overId: UniqueIdentifier | null = $derived(this.session?.overId ?? null);

	constructor(props: DndStateProps) {
		this.#props = props;
	}

	isDragging(id: UniqueIdentifier): boolean {
		return this.activeId === id;
	}

	/** Register a draggable/droppable node. Returns its own unregister thunk. */
	register(entry: DndNodeEntry): () => void {
		const existing = this.#nodes.findIndex((candidate) => candidate.id === entry.id);
		if (existing === -1) this.#nodes.push(entry);
		else this.#nodes[existing] = entry;

		return () => {
			const index = this.#nodes.indexOf(entry);
			if (index !== -1) this.#nodes.splice(index, 1);
		};
	}

	getEntry(id: UniqueIdentifier): DndNodeEntry | undefined {
		return this.#nodes.find((candidate) => candidate.id === id);
	}

	/** Measure a registered node right now, rather than reading the pick-up snapshot. */
	getRect(id: UniqueIdentifier): ClientRect | null {
		const entry = this.getEntry(id);
		return entry ? toClientRect(entry.node) : null;
	}

	/**
	 * Arm the pointer sensor. The session only opens once the activation constraint for this pointer
	 * type is met: 5 px of movement for mouse and pen, a 250 ms hold for touch (research R-03).
	 */
	startPointerDrag(entry: DndNodeEntry, event: PointerEvent, activator: HTMLElement): void {
		if (this.session || this.#pointer) return;
		if (entry.disabled()) return;
		if (event.button !== 0) return;
		if (!isActivationAllowed(event, activator)) return;

		this.#pointer = {
			entry,
			event,
			activator,
			origin: { x: event.clientX, y: event.clientY },
			pointerId: event.pointerId,
			timer: null,
			captured: false
		};
		this.#addPointerListeners();

		if (event.pointerType === 'touch') {
			this.#pointer.timer = setTimeout(() => this.#activatePointer(), TOUCH_ACTIVATION_DELAY);
		}
	}

	/** Pick the item up from the keyboard. There is no activation constraint on this path. */
	startKeyboardDrag(entry: DndNodeEntry, event: KeyboardEvent): void {
		if (this.session) return;
		if (entry.disabled()) return;

		const rect = toClientRect(entry.node);
		this.#openSession(entry, 'keyboard', event, centerOf(rect));
	}

	/** Apply a raw pointer delta: clamp it, re-resolve the drop target, notify. */
	move(delta: Coordinates): void {
		const session = this.session;
		if (!session) return;

		session.delta = delta;

		const nextOver = this.#resolveOver(session);
		if (nextOver !== session.overId) {
			session.overId = nextOver;
			this.#props.onOver?.(session);
		}
		this.#props.onMove?.(session);
	}

	/** The keyboard path: jump the drop target to a position in the identifier space. */
	moveToIndex(index: number): void {
		const session = this.session;
		if (!session) return;

		const id = this.#props.getItems()[index];
		if (id === undefined) return;

		const targetRect = session.rects.get(id);
		if (targetRect && session.activeRect) {
			session.delta = {
				x: targetRect.left - session.activeRect.left,
				y: targetRect.top - session.activeRect.top
			};
		}

		if (id !== session.overId) {
			session.overId = id;
			this.#props.onOver?.(session);
		}
		this.#props.onMove?.(session);
	}

	/** Drop at the current position. The caller commits the reorder from its `onEnd` hook. */
	end(): void {
		const session = this.session;
		if (!session) return;

		if (session.source === 'pointer') this.#suppressNextClick();
		this.#teardown();
		this.session = null;
		this.#props.onEnd?.(session);
	}

	/** Abandon the session. No reorder is ever committed from here. */
	cancel(): void {
		const session = this.session;
		if (!session) return;

		if (session.source === 'pointer') this.#suppressNextClick();
		session.cancelled = true;
		this.#teardown();
		this.session = null;
		this.#props.onCancel?.(session);
	}

	/**
	 * Swallow the `click` the browser synthesises once a pointer drag releases.
	 *
	 * The browser fires it at the nearest common ancestor of the `pointerdown` and `pointerup`
	 * targets, which for a handle inside a row that travels with the pointer is usually the row
	 * itself — so a drop would also *activate* the row. That is not hypothetical: `bits-ui`'s
	 * `Command.Item` selects on `click`, so dragging a row of the data table's `View` list toggled
	 * the column it had just moved.
	 *
	 * The listener is on the document and in the capture phase because the target is the browser's
	 * choice, not ours: it cannot be predicted from the dragged node, and stopping propagation on
	 * the way down is the only way to reach every listener below it, delegated ones included.
	 *
	 * Only a real session gets here — a press that never passed the activation threshold opens none
	 * — so an ordinary click on an item is untouched.
	 */
	#suppressNextClick(): void {
		const onClick = (event: MouseEvent) => {
			event.preventDefault();
			event.stopPropagation();
		};

		document.addEventListener('click', onClick, { capture: true, once: true });
		// The synthesised click is dispatched in the same task as the `pointerup`, so it always
		// arrives before this timeout. The timeout is for the drops that are *not* followed by one —
		// a pointer cancel, or a release whose targets share no ancestor — where a listener left
		// armed would go on to eat an unrelated click.
		setTimeout(() => document.removeEventListener('click', onClick, { capture: true }), 0);
	}

	/** Release every long-lived resource. Called from the root's `$effect` teardown. */
	destroy(): void {
		this.#teardown();
		this.session = null;
		this.#nodes.length = 0;
	}

	#candidatesFor(active: DndNodeEntry): DndNodeEntry[] {
		const all = this.#nodes.filter((entry) => entry.kind === 'item' && !entry.disabled());
		return this.#props.filterDroppables?.(all, active) ?? all;
	}

	#resolveOver(session: DragSession): UniqueIdentifier | null {
		const active = this.getEntry(session.activeId);
		const activeRect = session.activeRect;
		if (!active || !activeRect) return session.overId;

		const collisionRect = translateRect(activeRect, session.transform);

		// Dragged clear of the region it started in — there is nothing to drop onto, which is what
		// makes "dropped, no changes were made" reachable (contract §9).
		if (session.containerRect && !intersects(collisionRect, session.containerRect)) return null;

		const droppables = this.#candidatesFor(active).map((entry) => ({
			id: entry.id,
			rect: session.rects.get(entry.id) ?? toClientRect(entry.node)
		}));
		if (droppables.length === 0) return null;

		return this.#props.getCollisionDetection()({ collisionRect, droppables })[0]?.id ?? null;
	}

	#openSession(
		entry: DndNodeEntry,
		source: DragSource,
		activatorEvent: DragActivator,
		initialCoordinates: Coordinates
	): DragSession | null {
		const activeRect = toClientRect(entry.node);
		// Not `parentElement`: the item's direct parent may be a `display: contents` wrapper, which
		// has no box to clamp or collide against (see `layoutParentOf`).
		const parent = layoutParentOf(entry.node);

		// Every item is measured, disabled ones included: a disabled item is not a drop target but it
		// still occupies a slot the sorting strategy has to shift around. The map is built once and
		// never mutated afterwards — it is the frozen geometry the whole session reasons about.
		const measured: Array<[UniqueIdentifier, ClientRect]> = this.#nodes
			.filter((candidate) => candidate.kind === 'item' && candidate.id !== entry.id)
			.map((candidate) => [candidate.id, toClientRect(candidate.node)]);
		measured.push([entry.id, activeRect]);
		const rects = toRectMap(measured);

		const session = new DragSession({
			activeId: entry.id,
			source,
			activatorEvent,
			initialIndex: this.#props.getItems().indexOf(entry.id),
			initialCoordinates,
			activeRect,
			containerRect: parent ? toClientRect(parent) : null,
			rects,
			getModifiers: () => this.#props.getModifiers()
		});
		session.overId = entry.id;

		this.session = session;
		this.#addKeyListener();
		this.#props.onStart?.(session);
		return session;
	}

	#activatePointer(): void {
		const pointer = this.#pointer;
		if (!pointer || this.session) return;

		this.#clearPointerTimer();
		const session = this.#openSession(pointer.entry, 'pointer', pointer.event, pointer.origin);
		if (!session) return;

		try {
			pointer.activator.setPointerCapture(pointer.pointerId);
			pointer.captured = true;
		} catch {
			// Pointer capture is unavailable (jsdom, or a pointer that has already been released):
			// the document listeners still deliver the rest of the gesture.
		}
	}

	#onPointerMove = (event: PointerEvent): void => {
		const pointer = this.#pointer;
		if (!pointer || event.pointerId !== pointer.pointerId) return;

		const delta = { x: event.clientX - pointer.origin.x, y: event.clientY - pointer.origin.y };

		if (!this.session) {
			if (Math.sqrt(delta.x ** 2 + delta.y ** 2) < POINTER_ACTIVATION_DISTANCE) return;
			// A finger that moves before the hold elapses is scrolling, not dragging.
			if (pointer.event.pointerType === 'touch') {
				this.#abortPointer();
				return;
			}
			this.#activatePointer();
			if (!this.session) return;
		}

		this.move(delta);
	};

	#onPointerUp = (event: PointerEvent): void => {
		const pointer = this.#pointer;
		if (!pointer || event.pointerId !== pointer.pointerId) return;

		if (this.session) this.end();
		else this.#abortPointer();
	};

	#onPointerCancel = (event: PointerEvent): void => {
		const pointer = this.#pointer;
		if (!pointer || event.pointerId !== pointer.pointerId) return;

		if (this.session) this.cancel();
		else this.#abortPointer();
	};

	#onKeydown = (event: KeyboardEvent): void => {
		const session = this.session;
		if (!session) return;
		// The keypress that opened the session is still bubbling towards the document.
		if (event === session.activatorEvent) return;

		if (event.key === 'Escape') {
			event.preventDefault();
			this.cancel();
			return;
		}
		if (session.source !== 'keyboard') return;

		switch (event.key) {
			case ' ':
			case 'Enter':
				event.preventDefault();
				this.end();
				return;
			case 'Tab':
				// Focus may not leave a grabbed item.
				event.preventDefault();
				return;
			case 'ArrowUp':
			case 'ArrowDown':
			case 'ArrowLeft':
			case 'ArrowRight': {
				event.preventDefault();
				const index = this.#props.onArrowKey?.(event.key, session) ?? null;
				if (index !== null) this.moveToIndex(index);
				return;
			}
			default:
				return;
		}
	};

	#addPointerListeners(): void {
		if (this.#pointerListening) return;
		this.#pointerListening = true;
		document.addEventListener('pointermove', this.#onPointerMove);
		document.addEventListener('pointerup', this.#onPointerUp);
		document.addEventListener('pointercancel', this.#onPointerCancel);
	}

	#removePointerListeners(): void {
		if (!this.#pointerListening) return;
		this.#pointerListening = false;
		document.removeEventListener('pointermove', this.#onPointerMove);
		document.removeEventListener('pointerup', this.#onPointerUp);
		document.removeEventListener('pointercancel', this.#onPointerCancel);
	}

	#addKeyListener(): void {
		if (this.#keyListening) return;
		this.#keyListening = true;
		document.addEventListener('keydown', this.#onKeydown);
	}

	#removeKeyListener(): void {
		if (!this.#keyListening) return;
		this.#keyListening = false;
		document.removeEventListener('keydown', this.#onKeydown);
	}

	#clearPointerTimer(): void {
		if (this.#pointer?.timer != null) {
			clearTimeout(this.#pointer.timer);
			this.#pointer.timer = null;
		}
	}

	#abortPointer(): void {
		this.#clearPointerTimer();
		this.#releaseCapture();
		this.#pointer = null;
		this.#removePointerListeners();
	}

	#releaseCapture(): void {
		const pointer = this.#pointer;
		if (!pointer?.captured) return;
		try {
			pointer.activator.releasePointerCapture(pointer.pointerId);
		} catch {
			// The pointer is already gone; there is nothing left to release.
		}
		pointer.captured = false;
	}

	#teardown(): void {
		this.#abortPointer();
		this.#removeKeyListener();
	}
}

function isActivationAllowed(event: PointerEvent, activator: HTMLElement): boolean {
	const target = event.target;
	if (!(target instanceof Element)) return true;
	if (target.closest('[data-no-dnd]')) return false;
	if (target === activator) return true;

	const interactive = target.closest(INTERACTIVE_SELECTOR);
	if (!interactive || interactive === activator) return true;
	// A native control nested *inside* the activator keeps its own behaviour.
	return !activator.contains(interactive);
}

/**
 * The component layer: the root and item state classes, the four `Symbol`-keyed contexts and the
 * announcement builders.
 *
 * Everything sortable-specific lives here — `sortable-geometry.ts` and `sortable-dnd.svelte.ts`
 * stay free of `value`, orientation and screen-reader knowledge so `kanban` can import them
 * unchanged (research R-02).
 */

import { getContext, hasContext, setContext, tick } from 'svelte';

import type { Direction } from '$lib/components/ui/direction-provider/direction-provider.svelte.js';

import { DndState, type DndNodeEntry, type DragSession } from './sortable-dnd.svelte.js';
import {
	closestCenter,
	closestCorners,
	horizontalListSortingStrategy,
	rectSortingStrategy,
	resolveKeyboardIndex,
	restrictToHorizontalAxis,
	restrictToParentElement,
	restrictToVerticalAxis,
	verticalListSortingStrategy,
	type ClientRect,
	type Coordinates,
	type SortableArrowKey,
	type SortableCollisionDetection,
	type SortableModifier,
	type SortableOrientation,
	type SortableStrategy,
	type UniqueIdentifier
} from './sortable-geometry.js';

export type { SortableOrientation };

/** Upstream's `DragStartEvent` / `DragEndEvent`, narrowed to the two members a consumer can act on. */
export type SortableDragEvent = {
	active: { id: UniqueIdentifier };
	over: { id: UniqueIdentifier } | null;
};

export type SortableMoveEvent = SortableDragEvent & {
	activeIndex: number;
	overIndex: number;
};

/** What the move / over / end announcement builders receive. */
export type SortableAnnouncementArgs = SortableMoveEvent & { count: number };

/** What the pick-up and cancel announcement builders receive. */
export type SortableSessionAnnouncementArgs = {
	active: { id: UniqueIdentifier };
	activeIndex: number;
	count: number;
};

export type SortableAnnouncements = {
	onDragStart: (event: SortableSessionAnnouncementArgs) => string;
	onDragMove: (event: SortableAnnouncementArgs) => string;
	onDragOver: (event: SortableAnnouncementArgs) => string;
	onDragEnd: (event: SortableAnnouncementArgs) => string;
	onDragCancel: (event: SortableSessionAnnouncementArgs) => string;
};

export type SortableAccessibility = {
	/** Per-key override — anything left unsupplied keeps its default text. */
	announcements?: Partial<SortableAnnouncements>;
	screenReaderInstructions?: { draggable: string };
};

const NO_DROPPABLE_ANNOUNCEMENT =
	'Sortable item is no longer over a droppable area. Press escape to cancel.';

/** Copied verbatim from upstream `sortable.tsx:207-248`, punctuation and 1-based positions included. */
export const DEFAULT_SORTABLE_ANNOUNCEMENTS: SortableAnnouncements = {
	onDragStart: ({ active, activeIndex, count }) =>
		`Grabbed sortable item "${active.id}". Current position is ${activeIndex + 1} of ${count}. Use arrow keys to move, space to drop.`,
	onDragOver: ({ active, over, activeIndex, overIndex, count }) =>
		over
			? `Sortable item "${active.id}" moved ${overIndex > activeIndex ? 'down' : 'up'} to position ${overIndex + 1} of ${count}.`
			: NO_DROPPABLE_ANNOUNCEMENT,
	onDragMove: ({ active, over, activeIndex, overIndex, count }) =>
		over
			? `Sortable item "${active.id}" is moving ${overIndex > activeIndex ? 'down' : 'up'} to position ${overIndex + 1} of ${count}.`
			: NO_DROPPABLE_ANNOUNCEMENT,
	onDragEnd: ({ active, over, overIndex, count }) =>
		over
			? `Sortable item "${active.id}" dropped at position ${overIndex + 1} of ${count}.`
			: `Sortable item "${active.id}" dropped. No changes were made.`,
	onDragCancel: ({ active, activeIndex, count }) =>
		`Sorting cancelled. Sortable item "${active.id}" returned to position ${activeIndex + 1} of ${count}.`
};

/** Upstream `orientationConfig` (sortable.tsx:45-61), with `mixed`'s implicit default made explicit. */
const ORIENTATION_CONFIG: Record<
	SortableOrientation,
	{
		modifiers: SortableModifier[];
		strategy: SortableStrategy;
		collisionDetection: SortableCollisionDetection;
	}
> = {
	vertical: {
		modifiers: [restrictToVerticalAxis, restrictToParentElement],
		strategy: verticalListSortingStrategy,
		collisionDetection: closestCenter
	},
	horizontal: {
		modifiers: [restrictToHorizontalAxis, restrictToParentElement],
		strategy: horizontalListSortingStrategy,
		collisionDetection: closestCenter
	},
	mixed: {
		modifiers: [restrictToParentElement],
		strategy: rectSortingStrategy,
		collisionDetection: closestCorners
	}
};

const ZERO_RECT: ClientRect = { top: 0, left: 0, right: 0, bottom: 0, width: 0, height: 0 };

function arrowWordsFor(orientation: SortableOrientation): string {
	if (orientation === 'vertical') return 'up and down';
	if (orientation === 'horizontal') return 'left and right';
	return 'arrow';
}

/**
 * Upstream's runtime rule (sortable.tsx:143-147): object arrays must say how to identify an item.
 * Evaluated where the raw `value` is still in scope, so it surfaces on first render.
 */
export function assertItemValueGetter<T>(
	value: T[] | undefined,
	getItemValue: ((item: T) => UniqueIdentifier) | undefined
): void {
	if (getItemValue || !value?.length) return;
	const first = value[0];
	if (typeof first === 'object' && first !== null) {
		throw new Error('`getItemValue` is required when using array of objects');
	}
}

/** The identifier space: `value.map(getItemValue)`, or the items themselves for primitives. */
export function toItemValues<T>(
	value: T[] | undefined,
	getItemValue: ((item: T) => UniqueIdentifier) | undefined
): UniqueIdentifier[] {
	if (!value) return [];
	if (getItemValue) return value.map(getItemValue);
	return value.map((item) => item as unknown as UniqueIdentifier);
}

export type SortableRootStateProps = {
	readonly getItems: () => UniqueIdentifier[];
	readonly getCount: () => number;
	readonly getOrientation: () => SortableOrientation;
	readonly getStrategy: () => SortableStrategy | undefined;
	readonly getCollisionDetection: () => SortableCollisionDetection | undefined;
	readonly getModifiers: () => SortableModifier[] | undefined;
	readonly getFlatCursor: () => boolean;
	readonly getDir: () => Direction;
	readonly getAccessibility: () => SortableAccessibility | undefined;
	/** Performs the reorder. Never called when the drop produced no change. */
	readonly commit: (activeIndex: number, overIndex: number, event: SortableDragEvent) => void;
	readonly getOnDragStart: () => ((event: SortableDragEvent) => void) | undefined;
	readonly getOnDragMove: () => ((event: SortableDragEvent) => void) | undefined;
	readonly getOnDragOver: () => ((event: SortableDragEvent) => void) | undefined;
	readonly getOnDragEnd: () => ((event: SortableDragEvent) => void) | undefined;
	readonly getOnDragCancel: () => ((event: SortableDragEvent) => void) | undefined;
	/** The one `$props.id()` the live region and instructions ids derive from. */
	readonly id: string;
};

/** One instance per `<Sortable>`. Published on context; every part reads it. */
export class SortableRootState {
	// `$derived` below is lazy at runtime, but svelte-check's static analysis cannot see that and
	// flags the field as used before its constructor assignment.
	#props!: SortableRootStateProps;

	readonly dnd: DndState;

	readonly items: UniqueIdentifier[] = $derived(this.#props.getItems());
	readonly count: number = $derived(this.#props.getCount());
	readonly orientation: SortableOrientation = $derived(this.#props.getOrientation());
	readonly flatCursor: boolean = $derived(this.#props.getFlatCursor());
	readonly dir: Direction = $derived(this.#props.getDir());

	readonly config = $derived.by(() => {
		const base = ORIENTATION_CONFIG[this.orientation];
		return {
			modifiers: this.#props.getModifiers() ?? base.modifiers,
			strategy: this.#props.getStrategy() ?? base.strategy,
			collisionDetection: this.#props.getCollisionDetection() ?? base.collisionDetection
		};
	});

	readonly activeIndex: number = $derived(
		this.activeId === null ? -1 : this.items.indexOf(this.activeId)
	);
	readonly overIndex: number = $derived(
		this.overId === null ? -1 : this.items.indexOf(this.overId)
	);

	/** Incremented by every mounted `<Sortable.Overlay>`; drives the R-08 displacement rule. */
	overlayCount = $state(0);
	readonly hasOverlay: boolean = $derived(this.overlayCount > 0);

	/** The live region's text. Written only when it actually changes (research R-10). */
	announcement = $state('');

	readonly instructions: string = $derived(
		this.#props.getAccessibility()?.screenReaderInstructions?.draggable ??
			`To pick up a sortable item, press space or enter. While dragging, use the ${arrowWordsFor(this.orientation)} keys to move the item. Press space or enter again to drop the item in its new position, or press escape to cancel.`
	);

	readonly liveRegionId: string = $derived(`${this.#props.id}-live`);
	readonly instructionsId: string = $derived(`${this.#props.id}-instructions`);

	readonly #announcements: SortableAnnouncements = $derived.by(() => {
		const overrides = this.#props.getAccessibility()?.announcements;
		return {
			onDragStart: overrides?.onDragStart ?? DEFAULT_SORTABLE_ANNOUNCEMENTS.onDragStart,
			onDragMove: overrides?.onDragMove ?? DEFAULT_SORTABLE_ANNOUNCEMENTS.onDragMove,
			onDragOver: overrides?.onDragOver ?? DEFAULT_SORTABLE_ANNOUNCEMENTS.onDragOver,
			onDragEnd: overrides?.onDragEnd ?? DEFAULT_SORTABLE_ANNOUNCEMENTS.onDragEnd,
			onDragCancel: overrides?.onDragCancel ?? DEFAULT_SORTABLE_ANNOUNCEMENTS.onDragCancel
		};
	});

	constructor(props: SortableRootStateProps) {
		this.#props = props;

		this.dnd = new DndState({
			getItems: () => this.items,
			getModifiers: () => this.config.modifiers,
			getCollisionDetection: () => this.config.collisionDetection,
			// Cross-region dragging is out of scope: a drag resolves only against the region it
			// started in (research R-24).
			filterDroppables: (candidates, active) =>
				candidates.filter((candidate) => candidate.containerId === active.containerId),
			onStart: (session) => this.#onSessionStart(session),
			onMove: (session) => this.#onSessionMove(session),
			onOver: (session) => this.#onSessionOver(session),
			onEnd: (session) => this.#onSessionEnd(session),
			onCancel: (session) => this.#onSessionCancel(session),
			onArrowKey: (key, session) => this.resolveArrowKey(key, session)
		});
	}

	// Plain getters rather than `$derived` fields: `dnd` is assigned in the constructor, so a field
	// initializer reading it would be a use-before-initialization. `dnd.activeId` is itself derived,
	// so reading through a getter stays reactive.
	get activeId(): UniqueIdentifier | null {
		return this.dnd.activeId;
	}

	get overId(): UniqueIdentifier | null {
		return this.dnd.overId;
	}

	indexOf(value: UniqueIdentifier): number {
		return this.items.indexOf(value);
	}

	/**
	 * The transform an item renders with, per research R-06/R-08: nothing while idle, the sorting
	 * strategy's shift for every other item, and — for the dragged item — nothing when an overlay is
	 * mounted, or the clamped pointer delta when there is none.
	 */
	getItemTransform(value: UniqueIdentifier, strategy?: SortableStrategy): Coordinates | null {
		const session = this.dnd.session;
		if (!session) return null;

		if (value === session.activeId) return this.hasOverlay ? null : session.transform;

		const activeIndex = this.activeIndex;
		const overIndex = this.overIndex;
		const index = this.indexOf(value);
		if (activeIndex < 0 || overIndex < 0 || index < 0) return null;

		return (strategy ?? this.config.strategy)({
			index,
			activeIndex,
			overIndex,
			rects: this.items.map((id) => session.rects.get(id) ?? ZERO_RECT),
			activeRect: session.activeRect
		});
	}

	/** The floating element's clamped delta. */
	getOverlayTransform(): Coordinates | null {
		return this.dnd.session?.transform ?? null;
	}

	/** The active item's snapshot box, which the floating element is sized and placed from. */
	getOverlayRect(): ClientRect | null {
		return this.dnd.session?.activeRect ?? null;
	}

	/** Write the live region, but only when the text actually changed (research R-10). */
	announce(text: string): void {
		if (text !== this.announcement) this.announcement = text;
	}

	/** Which index an arrow key moves the grabbed item to, measured from its current drop target. */
	resolveArrowKey(key: SortableArrowKey, session: DragSession): number | null {
		const containerId = this.dnd.getEntry(session.activeId)?.containerId ?? null;

		const candidates = this.items.map((id) => {
			const entry = this.dnd.getEntry(id);
			return {
				id,
				// An item in another region is not a target, for the same reason the pointer path
				// filters droppables by region (research R-24).
				disabled: (entry?.disabled() ?? true) || (entry?.containerId ?? null) !== containerId,
				rect: session.rects.get(id) ?? null
			};
		});

		return resolveKeyboardIndex({
			key,
			orientation: this.orientation,
			dir: this.dir,
			activeIndex: this.items.indexOf(session.overId ?? session.activeId),
			candidates
		});
	}

	#eventOf(session: DragSession): SortableDragEvent {
		return {
			active: { id: session.activeId },
			over: session.overId === null ? null : { id: session.overId }
		};
	}

	#announcementArgs(session: DragSession): SortableAnnouncementArgs {
		const event = this.#eventOf(session);
		return {
			...event,
			activeIndex: this.items.indexOf(session.activeId),
			overIndex: session.overId === null ? -1 : this.items.indexOf(session.overId),
			count: this.count
		};
	}

	#onSessionStart(session: DragSession): void {
		const event = this.#eventOf(session);
		this.#props.getOnDragStart()?.(event);
		this.announce(
			this.#announcements.onDragStart({
				active: event.active,
				activeIndex: session.initialIndex,
				count: this.count
			})
		);
	}

	#onSessionOver(session: DragSession): void {
		this.#props.getOnDragOver()?.(this.#eventOf(session));
		this.announce(this.#announcements.onDragOver(this.#announcementArgs(session)));
	}

	#onSessionMove(session: DragSession): void {
		this.#props.getOnDragMove()?.(this.#eventOf(session));
		this.announce(this.#announcements.onDragMove(this.#announcementArgs(session)));
	}

	/**
	 * Keep the grabbed activator focused across the reorder: committing a keyboard drop relocates the
	 * item's node, and relocating a focused node runs the removal steps first, which blurs it. The
	 * restore is scheduled after the commit so `tick()` resolves once the node is back in place.
	 */
	#retainFocus(session: DragSession): void {
		if (session.source !== 'keyboard') return;

		const element = document.activeElement;
		if (!(element instanceof HTMLElement)) return;

		void tick().then(() => {
			if (element.isConnected && document.activeElement !== element) element.focus();
		});
	}

	#onSessionEnd(session: DragSession): void {
		const event = this.#eventOf(session);
		const args = this.#announcementArgs(session);

		// A release with nothing under it commits nothing. FR-019 routes that to `onDragCancel`,
		// while the announcement stays upstream's "dropped, no changes were made" text.
		if (session.overId === null) {
			this.#props.getOnDragCancel()?.(event);
			this.announce(this.#announcements.onDragEnd(args));
			return;
		}

		this.#props.getOnDragEnd()?.(event);
		this.announce(this.#announcements.onDragEnd(args));
		this.#props.commit(args.activeIndex, args.overIndex, event);
		this.#retainFocus(session);
	}

	#onSessionCancel(session: DragSession): void {
		const event = this.#eventOf(session);
		this.#props.getOnDragCancel()?.(event);
		this.announce(
			this.#announcements.onDragCancel({
				active: event.active,
				activeIndex: session.initialIndex,
				count: this.count
			})
		);
	}
}

export type SortableItemStateProps = {
	readonly root: SortableRootState;
	readonly getValue: () => UniqueIdentifier;
	readonly getDisabled: () => boolean;
	readonly getStrategy: () => SortableStrategy | undefined;
	/** An item rendered inside `<Sortable.Overlay>` is a preview: it never registers or moves. */
	readonly inOverlay: boolean;
	/** The item's own `$props.id()` — the handle's `aria-controls` target. */
	readonly id: string;
};

/** One instance per `<Sortable.Item>`. The Svelte counterpart of dnd-kit's `useSortable()`. */
export class SortableItemState {
	// Same lazy-`$derived` caveat as SortableRootState#props.
	#props!: SortableItemStateProps;

	/** The rendered element, bound by the part; drives registration. */
	node = $state<HTMLElement | null>(null);
	/** Which element starts a drag — the item when `asHandle`, otherwise the handle. */
	activator = $state<HTMLElement | null>(null);

	readonly value: UniqueIdentifier = $derived(this.#props.getValue());
	readonly disabled: boolean = $derived(this.#props.getDisabled());
	readonly index: number = $derived(this.#props.root.indexOf(this.value));
	readonly isDragging: boolean = $derived(
		!this.#props.inOverlay && this.#props.root.activeId === this.value
	);
	readonly transform: Coordinates | null = $derived(
		this.#props.inOverlay
			? null
			: this.#props.root.getItemTransform(this.value, this.#props.getStrategy())
	);

	/** dnd-kit's `useSortable().attributes`, minus the `role` the handle already has (research R-11). */
	readonly activatorAttrs = $derived({
		tabindex: this.disabled ? undefined : 0,
		'aria-roledescription': 'sortable',
		'aria-describedby': this.#props.root.instructionsId,
		'aria-disabled': this.disabled ? ('true' as const) : undefined,
		'aria-pressed': this.isDragging ? ('true' as const) : undefined
	});

	constructor(props: SortableItemStateProps) {
		this.#props = props;
	}

	get root(): SortableRootState {
		return this.#props.root;
	}

	get id(): string {
		return this.#props.id;
	}

	get inOverlay(): boolean {
		return this.#props.inOverlay;
	}

	setActivator(element: HTMLElement | null): void {
		this.activator = element;
	}

	/** Register this item as draggable and droppable. Returns its own unregister thunk. */
	register(node: HTMLElement, containerId: UniqueIdentifier | null): () => void {
		return this.root.dnd.register({
			id: this.value,
			kind: 'item',
			containerId,
			node,
			disabled: () => this.disabled
		});
	}

	#entry(): DndNodeEntry | undefined {
		return this.root.dnd.getEntry(this.value);
	}

	onActivatorPointerDown(event: PointerEvent, activator: HTMLElement): void {
		if (this.disabled || this.inOverlay) return;
		const entry = this.#entry();
		if (!entry) return;
		this.root.dnd.startPointerDrag(entry, event, activator);
	}

	onActivatorKeydown(event: KeyboardEvent): void {
		if (this.disabled || this.inOverlay) return;
		// An open session is owned by the engine's own document listener.
		if (this.root.dnd.session) return;
		if (event.key !== ' ' && event.key !== 'Enter') return;

		const entry = this.#entry();
		if (!entry) return;

		event.preventDefault();
		this.root.dnd.startKeyboardDrag(entry, event);
	}
}

/** What `<Sortable.Content>` publishes to the items inside it. */
export type SortableContentContext = {
	readonly id: string;
	readonly getStrategy: () => SortableStrategy | undefined;
};

const SORTABLE_CONTEXT_KEY = Symbol('sortable');
const SORTABLE_CONTENT_CONTEXT_KEY = Symbol('sortable-content');
const SORTABLE_ITEM_CONTEXT_KEY = Symbol('sortable-item');
const SORTABLE_OVERLAY_CONTEXT_KEY = Symbol('sortable-overlay');

export function setSortableContext(state: SortableRootState): SortableRootState {
	return setContext(SORTABLE_CONTEXT_KEY, state);
}

/** Read the root state, naming the misused part in the error when there is no `<Sortable>` above. */
export function getSortableContext(part = 'Sortable.Content'): SortableRootState {
	if (!hasContext(SORTABLE_CONTEXT_KEY)) {
		throw new Error(`\`<${part}>\` must be used within \`<Sortable>\`.`);
	}
	return getContext<SortableRootState>(SORTABLE_CONTEXT_KEY);
}

export function setSortableContentContext(context: SortableContentContext): SortableContentContext {
	return setContext(SORTABLE_CONTENT_CONTEXT_KEY, context);
}

export function hasSortableContentContext(): boolean {
	return hasContext(SORTABLE_CONTENT_CONTEXT_KEY);
}

export function getSortableContentContext(): SortableContentContext | undefined {
	return hasSortableContentContext()
		? getContext<SortableContentContext>(SORTABLE_CONTENT_CONTEXT_KEY)
		: undefined;
}

export function setSortableOverlayContext(): boolean {
	return setContext(SORTABLE_OVERLAY_CONTEXT_KEY, true);
}

export function hasSortableOverlayContext(): boolean {
	return hasContext(SORTABLE_OVERLAY_CONTEXT_KEY);
}

export function setSortableItemContext(state: SortableItemState): SortableItemState {
	return setContext(SORTABLE_ITEM_CONTEXT_KEY, state);
}

export function getSortableItemContext(): SortableItemState {
	if (!hasContext(SORTABLE_ITEM_CONTEXT_KEY)) {
		throw new Error('`<Sortable.ItemHandle>` must be used within `<Sortable.Item>`.');
	}
	return getContext<SortableItemState>(SORTABLE_ITEM_CONTEXT_KEY);
}

/**
 * Read the nearest `<Sortable.Item>`'s state — this port's counterpart of dnd-kit's `useSortable()`,
 * for consumers composing their own parts inside an item.
 */
export function useSortable(): SortableItemState {
	return getSortableItemContext();
}
